-- Confirm the partition isn't registered
SHOW PARTITIONS sales;

-- Option 1: scan and register all missing partitions
MSCK REPAIR TABLE sales;

-- Option 2: add just the one new partition directly (often faster)
ALTER TABLE sales ADD PARTITION (year=2026, month=10)
  LOCATION 's3://data-lake/sales/year=2026/month=10/';
